import React, { useState } from 'react';
import api from '../services/api';

const BuscarMotorista = () => {
    const [placa, setPlaca] = useState('');
    const [motorista, setMotorista] = useState(null);
    const [erro, setErro] = useState('');

    // Função para buscar o motorista
    const buscarMotorista = () => {
        api.get(`/buscar/${placa}`)
            .then(response => {
                setMotorista(response.data);
                setErro('');
            })
            .catch(() => {
                setMotorista(null);
                setErro('❌ Motorista não encontrado.');
            });
    };

    // Função para excluir motorista
    const excluirMotorista = () => {
        if (window.confirm('Tem certeza que deseja excluir este motorista?')) {
            api.delete(`/deletar/${motorista.id}`)
                .then(() => {
                    alert('🚗 Motorista excluído com sucesso!');
                    setMotorista(null);
                })
                .catch(() => {
                    alert('❌ Erro ao excluir motorista!');
                });
        }
    };

    return (
        <div className="container">
            <h2>Buscar Motorista</h2>
            <input
                type="text"
                placeholder="Digite a placa"
                value={placa}
                onChange={(e) => setPlaca(e.target.value)}
            />
            <button onClick={buscarMotorista}>Buscar</button>

            {motorista && (
                <div className="resultado-busca">
                    <h3><strong>{motorista.nome}</strong></h3>
                    <p><strong>Placa:</strong> {motorista.placa}</p>
                    <p><strong>Modelo:</strong> {motorista.modelo} ({motorista.ano})</p>
                    <p><strong>Função:</strong> {motorista.funcao}</p>

                    {/* Botões de Editar e Excluir */}
                    <div className="botoes-acoes">
                        <button className="btn-editar" onClick={() => alert('🛠 Função de edição ainda não implementada')}>
                            ✏️ Editar
                        </button>
                        <button className="btn-excluir" onClick={excluirMotorista}>
                            🗑️ Excluir
                        </button>
                    </div>
                </div>
            )}

            {erro && <p>{erro}</p>}
        </div>
    );
};

export default BuscarMotorista;
